values ('bbbb0004-0000-4000-8000-000000000003', 'en', null, 'Introduction to Chemistry', 'A first tour of matter — atoms, bonds, the mole, gases, solutions, and reactions — with just enough math to make predictions. Structure adapted from OpenStax Chemistry 2e (CC BY 4.0).', null, 'foundations', 3, true, 'science', '{}')
